export const AGOAC_BOARD_NAMES=Object.freeze(Object.keys(BOARD_RECORDS));
function decodedTags(encoded){
 const output={};
 for(const raw of encoded.split(';')){
  if(!raw)continue;
  const [name,...pieces]=raw.split(':');
  if(!/^[a-z_]+$/.test(name)||Object.hasOwn(output,name))
   throw Error('Invalid pinned mapsheet terrain');
  const numbers=pieces.map(Number);
  if(numbers.some(n=>!Number.isInteger(n)))throw Error('Invalid mapsheet terrain number');
  output[name]=numbers;
 }
 return output;
}
// Independent engine tiles; preserve the original source labels and terrain.
// The engine currently treats bridges as top-level traversal surfaces and
// retains under-bridge water separately for future stacked-level semantics.
export function buildAgoacSheet(name,{sheet=0,rotation=0}={}){
 const entries=BOARD_RECORDS[name];
 if(!entries||![0,1].includes(sheet)||![0,3].includes(rotation))
  throw Error('Unknown AGoAC physical mapsheet or orientation');
 const tiles=[];
 for(let i=0;i<entries.length;i++){
  const [level,sourceTerrain,theme]=entries[i];
  const originalCol=i%16,originalRow=Math.floor(i/16);
  const localCol=rotation===3?15-originalCol:originalCol;
  const localRow=rotation===3?16-originalRow:originalRow;
  const col=sheet*16+localCol,row=localRow,r=row-8;
  const q=col-16-Math.floor(r/2);
  const tags=decodedTags(sourceTerrain);
  const water=tags.water?.[0]??0,woods=tags.woods?.[0]??0;
  const bridge=tags.bridge?.[0]??0,bridgeElev=tags.bridge_elev?.[0]??0;
  const mask=tags.road?.[1]??0;
  const roadEdges=Array.from({length:6},(_,d)=>d).filter(d=>(mask&(1<<d))!==0)
   .map(d=>(d+rotation)%6);
  const isBridge=bridge>0;
  const depth=isBridge?0:water;
  const height=isBridge?level+bridgeElev:level-depth;
  const type=isBridge?'bridge':water?'water':woods>=2?'heavy':
   woods?'woods':tags.rough?'rough':'plain';
  const tile={q,r,sheet,type,height,depth,
   surface:isBridge?height:level,roadEdges,
   printedSheet:name,printedHex:String(originalCol+1).padStart(2,'0')+
    String(originalRow+1).padStart(2,'0'),
   theme,sourceTerrain};
  if(isBridge)tile.bridge={cf:tags.bridge_cf?.[0]??0,
   elevation:bridgeElev,underlyingWater:water};
  if(tags.foliage_elev)tile.foliageElevation=tags.foliage_elev[0];
  tiles.push(tile);
 }
 if(tiles.length!==272||new Set(tiles.map(t=>t.q+','+t.r)).size!==272)
  throw Error('Incomplete AGoAC physical mapsheet');
 return tiles;
}
